// WindowControls — Gtk.WindowControls
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles windowcontrols with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { PackType } from "@/lib/enums"

export interface WindowControlsProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** utf8, from Gtk.WindowControls */
  decorationLayout?: string

  /** PackType, from Gtk.WindowControls */
  side?: PackType

  /** gboolean, from Gtk.WindowControls */
  useNativeControls?: boolean
}

export function WindowControls({ className, children }: WindowControlsProps) {
  return (
    <div className={cn("gap-[3px]", className)}>
      {children}
    </div>
  )
}
